195	struct Edge_Record {
196		Edge_Record() {
197		}
198		Edge_Record(std::unordered_map<uint32_t, Mat4>& VQ, Halfedge_Mesh::EdgeRef e) : edge(e) {
199			
200			// Compute the combined quadric from the edge endpoints.
201	        // -> Build the 3x3 linear system whose solution minimizes the quadric error
202	        //    associated with these two endpoints.
203	        // -> Use this system to solve for the optimal position, and store it in
204	        //    Edge_Record::optimal.
205	        // -> Also store the cost associated with collapsing this edge in
206	        //    Edge_Record::cost.
207		}
208		Halfedge_Mesh::EdgeRef edge;
209		Vec3 optimal;
210		float score;
211	};
