213	bool operator<(const Edge_Record& r1, const Edge_Record& r2) {
214		if (r1.score != r2.score) {
215			return (r1.score < r2.score);
216		}
217		Halfedge_Mesh::EdgeRef e1 = r1.edge;
218		Halfedge_Mesh::EdgeRef e2 = r2.edge;
219		return &*e1 < &*e2;
220	}
