222	template<class T> struct MutablePriorityQueue {
223		void insert(const T& item) {
224			queue.insert(item);
225		}
226		void remove(const T& item) {
227			if (queue.find(item) != queue.end()) {
228				queue.erase(item);
229			}
230		}
231		const T& top() const {
232			return *(queue.begin());
233		}
234		void pop() {
235			queue.erase(queue.begin());
236		}
237		size_t size() {
238			return queue.size();
239		}
240	
241		std::set<T> queue;
242	};
